<div class="fork-records">
<p class="notice"><?=e($bg['notice'])?></p>
<h3>Original question: <?=e($bg['question']['title'])?></h3><?=prose($bg['question']['question'])?>
<p class="fine">Asked by <?=e($bg['question']['display_name']?:'Anonymous requester')?> · identity unverified</p><?php profile_links($bg['question']['profiles']); ?>
<?php foreach(['context'=>'Background','success'=>'Objectives','previous'=>'Previous research','constraints_text'=>'Constraints and limitations','questions'=>'Specific questions','references_text'=>'References'] as $key=>$label): if(!$bg['question'][$key])continue; ?><h4><?=e($label)?></h4><?=prose($bg['question'][$key])?><?php endforeach ?>
<?php foreach($bg['contributions'] as $c): ?><article><h3>Inherited contribution: <?=e($c['summary'])?></h3><p class="fine">Contributor: <?=e($c['display_name']?:'Anonymous volunteer')?> · <?=e($c['created_at'])?> UTC · <?=e($c['license']??'CC BY 4.0')?> · <?=e($c['id'])?></p><?php profile_links($c['profiles']); ?><a class="text-action" href="/research/<?=e($bg['question']['slug'])?>#contribution-<?=e($c['id'])?>">Read original contribution and current status</a><?=prose($c['body'])?><?php foreach(['methodology'=>'Method','sources'=>'Sources','uncertainty'=>'Uncertainty','limitations'=>'Limitations','open_questions'=>'Open questions','next_actions'=>'Suggested next steps'] as $key=>$label): ?><h4><?=e($label)?></h4><?=prose($c[$key]?:'Not supplied')?><?php endforeach ?></article><?php endforeach ?>
<?php foreach($bg['results'] as $s): ?><article><h3>Inherited task result</h3><p class="fine">Contributor: <?=e($s['display_name']?:'Anonymous volunteer')?> · <?=e($s['created_at'])?> UTC · <?=e($s['license']??'CC BY 4.0')?></p><a class="text-action" href="/research/<?=e($bg['question']['slug'])?>/results/<?=e($s['id'])?>">Read original result and current status</a><?php foreach(['body'=>'Findings','methodology'=>'Method','sources'=>'Sources','limitations'=>'Limitations'] as $key=>$label): ?><h4><?=e($label)?></h4><?=prose($s[$key])?><?php endforeach ?><details><summary>Inherited claim and source records</summary><pre><?=e(json_encode($s['evidence'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details></article><?php endforeach ?>
<?php foreach($bg['findings'] as $f): ?><article><h3>Inherited finding (historical source classification: <?=e($f['classification'])?>)</h3><?=prose($f['statement'])?><?=prose($f['rationale'])?><p class="fine">Source finding ID: <?=e($f['id'])?>. This classification does not verify the new question.</p></article><?php endforeach ?>
<?php if($bg['attachments']): ?><h3>Public source attachments</h3><p class="fine">Original links only. Files are not copied and keep their original publication and rights restrictions.</p><ul><?php foreach($bg['attachments'] as $a): ?><li><a class="text-action" href="/files/<?=e($a['id'])?>"><?=e($a['original_name'])?></a></li><?php endforeach ?></ul><?php endif ?>
<?php if($bg['inherited_background']): $ancestor=$bg['inherited_background']; ?><details><summary>Earlier fork background · context v<?=e($ancestor['context_version'])?></summary><p class="fine">Source: <?=e($ancestor['parent']['title'])?> · <?=e($ancestor['parent']['id'])?> · Snapshot <?=e($ancestor['snapshot_id'])?> · SHA-256 <?=e($ancestor['snapshot_sha256'])?></p><?php $renderBackground($ancestor['background']); ?></details><?php endif ?>
</div>
